--

CREATE FUNCTION public.update_user_activity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE user_login 
    SET last_login = NOW(), is_active = TRUE 
    WHERE email_id = NEW.assigned_to_email;
    RETURN NEW;
END;
$$;


